DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_owner INT;
  cur_count INT;
BEGIN
  FOR rec IN SELECT * FROM playlist_events ORDER BY event_id LOOP
    SELECT status, owner_user_id, track_count INTO cur_status, cur_owner, cur_count
      FROM playlists WHERE playlist_id = rec.playlist_id;

    IF rec.event_type = 1 AND cur_status = 'inactive' THEN
      UPDATE playlists
        SET status = 'active', owner_user_id = rec.user_id, track_count = 0
        WHERE playlist_id = rec.playlist_id;
    ELSIF rec.event_type = 2 AND cur_status = 'active' AND cur_owner = rec.user_id THEN
      UPDATE playlists
        SET track_count = track_count + 1
        WHERE playlist_id = rec.playlist_id;
    ELSIF rec.event_type = 3 AND cur_status = 'active' AND cur_owner = rec.user_id THEN
      UPDATE playlists
        SET status = 'archived'
        WHERE playlist_id = rec.playlist_id;
    ELSIF rec.event_type = 4 AND cur_status = 'active' AND cur_owner = rec.user_id THEN
      UPDATE playlists
        SET owner_user_id = rec.new_owner_id
        WHERE playlist_id = rec.playlist_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM playlists ORDER BY playlist_id;
